package com.himeros.premium;import com.himeros.billing.PaymentCaptured;import java.time.*;import java.util.*;import org.springframework.context.event.EventListener;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service public class PremiumService{private final SubscriptionRepository repo;public PremiumService(SubscriptionRepository r){repo=r;}@EventListener public void on(PaymentCaptured e){Instant start=Instant.now();long days=switch(e.plan()){case"MONTHLY"->30;case"QUARTERLY"->90;case"YEARLY"->365;default->throw new IllegalArgumentException("Unknown plan");};repo.save(new Subscription(e.userId(),e.plan(),e.paymentId(),start,start.plus(Duration.ofDays(days))));}@Transactional(readOnly=true)public Optional<SubscriptionView> active(UUID user){return repo.active(user,Subscription.Status.ACTIVE,Instant.now()).stream().findFirst().map(s->new SubscriptionView(s.id(),s.plan(),s.status().name(),s.starts(),s.ends(),s.payment()));}public record SubscriptionView(UUID id,String plan,String status,Instant startsAt,Instant endsAt,UUID paymentId){}}
